function launch(run: Run) {
  const info = run.info
  info.status = 'running'
  info.startedAt = new Date().toISOString()
  const d = run.dispatch!
  try {
    run.files = store.openRun(info.id)
    pushLine(run, 'system', `$ ${info.binary} ${info.argv.join(' ')}   (${d.resolved})`)
    run.proc = startProcess(d, { ...same handlers... })
    info.pid = run.proc.pid
  } catch (err) {
    const msg = `launch failed: ${(err as Error).message}`
    log.warn(`run ${info.id}: ${msg}`)
    pushLine(run, 'system', msg)
    if (!info.error) info.error = msg
    // onExit() sets status 'failed' (code null, not killed/diverged), endedAt, pid=null,
    // closes run.files, releases the GPU flag, persists, emits updated/exit,
    // settles waiters, resolves run.exited and re-enters pump() for the next queued run.
    onExit(run, null, null)
    return
  }
  if (run.spec?.gpu) gpu.setActive(true)
  log.info(...)
  if (run.announced) emit({ type: 'updated', run: snapshot(run) })
  void persistIndex()
}
```

Do not rethrow: start() then returns/emits 'started' with the run already in status 'failed' and error set (the caller sees the failure in the RunInfo rather than a 500 that leaves state inconsistent), and onExit's pump() call lets other queued runs proceed. Optionally gate the 'updated'/'exit' emits in onExit on run.announced, or emit them after 'started', so a run that fails during start() does not publish exit before started. Add a manager.test.ts case that points runsDir at a regular file (mkdirSync -> ENOTDIR) and asserts: start() resolves with status 'failed' and error /launch failed/, a second GPU run is not blocked (gets launched), and stop() on the failed run returns immediately.

