```ts
function launch(run: Run) {
  const info = run.info
  const d = run.dispatch!
  info.status = 'running'
  info.startedAt = new Date().toISOString()
  try {
    run.files = store.openRun(info.id)
    pushLine(run, 'system', `$ ${info.binary} ${info.argv.join(' ')}   (${d.resolved})`)
    run.proc = startProcess(d, { line: ..., exit: ..., spawnError: ... })   // unchanged handlers
  } catch (err) {
    const msg = `failed to start: ${(err as Error).message}`
    pushLine(run, 'system', msg)          // run.files may be null; pushLine already uses ?.
    if (!info.error) info.error = msg
    log.warn(`run ${info.id} ${msg}`)
    onExit(run, -1, null)                 // -> status 'failed', endedAt, pid=null, closes any opened files,
    return                                //    releases the GPU flag, emits updated/exit, settles waiters,
  }                                       //    resolves run.exited, and re-pumps the queue
  info.pid = run.proc.pid
  if (run.spec?.gpu) gpu.setActive(true)
  log.info(...)
  if (run.announced) emit({ type: 'updated', run: snapshot(run) })
  void persistIndex()
}
```

Notes: onExit with code -1 (killRequested/diverged false) yields status 'failed' and keeps the error we set; calling it synchronously means start() resolves with a 'failed' snapshot and emits 'started' normally instead of rejecting with a 500, and the onExit()->pump() path (child 'close' listener) can no longer crash the server. Add a regression test in server/src/runs/manager.test.ts: make config.runsDir a plain file (or otherwise force store.openRun to throw), call start(), and assert the run is 'failed' with an error, that a subsequent GPU run launches, and that stop() on the failed run returns immediately. Optional adjacent hardening (not required for this finding): in store.ts openRun(), attach 'error' listeners to the two createWriteStream handles so an async open failure does not become an unhandled 'error' event.
